69: static void set_thread_affinity_mask( std::size_t maskSize, const basic_mask_t* threadMask ) {
70: #if __FreeBSD__ || __NetBSD__ || __OpenBSD__
71:     if( cpuset_setaffinity( CPU_LEVEL_WHICH, CPU_WHICH_TID, -1, maskSize, threadMask ) )
72: #else /* __unix__ */
