108: void affinity_helper::protect_affinity_mask( bool restore_process_mask ) {
109:     if( threadMask == nullptr && num_masks ) { // TODO: assert num_masks validity?
110:         threadMask = new basic_mask_t [num_masks];
111:         std::memset( threadMask, 0, curMaskSize );
112:         get_thread_affinity_mask( curMaskSize, threadMask );
113:         if( restore_process_mask ) {
114:             __TBB_ASSERT( process_mask, "A process mask is requested but not yet stored" );
115:             is_changed = memcmp( process_mask, threadMask, curMaskSize );
116:             if( is_changed )
117:                 set_thread_affinity_mask( curMaskSize, process_mask );
118:         } else {
119:             // Assume that the mask will be changed by the caller.
120:             is_changed = 1;
121:         }
122:     }
