133: static int theNumProcs;
134: 
135: static void initialize_hardware_concurrency_info () {
136:     int err;
137:     int availableProcs = 0;
138:     int numMasks = 1;
139:     int maxProcs = sysconf(_SC_NPROCESSORS_ONLN);
140:     basic_mask_t* processMask;
141:     const std::size_t BasicMaskSize =  sizeof(basic_mask_t);
142:     for (;;) {
143:         const int curMaskSize = BasicMaskSize * numMasks;
144:         processMask = new basic_mask_t[numMasks];
145:         std::memset( processMask, 0, curMaskSize );
146: #if __FreeBSD__ || __NetBSD__ || __OpenBSD__
147:         // CPU_LEVEL_WHICH - anonymous (current) mask, CPU_LEVEL_CPUSET - assigned mask
148:         err = cpuset_getaffinity( CPU_LEVEL_WHICH, CPU_WHICH_PID, -1, curMaskSize, processMask );
149:         if ( !err || errno != ERANGE || curMaskSize * CHAR_BIT >= 16 * 1024 )
150:             break;
151: #else /* __unix__ */
152:         int pid = getpid();
153:         err = sched_getaffinity( pid, curMaskSize, processMask );
154:         if ( !err || errno != EINVAL || curMaskSize * CHAR_BIT >= 256 * 1024 )
155:              break;
156: #endif
157:         delete[] processMask;
158:         numMasks <<= 1;
159:     }
160:     if ( !err ) {
161:         // We have found the mask size and captured the process affinity mask into processMask.
162:         num_masks = numMasks; // do here because it's needed for affinity_helper to work
163: #if __unix__
164:         // For better coexistence with libiomp which might have changed the mask already,
165:         // check for its presence and ask it to restore the mask.
166:         dynamic_link_handle libhandle;
167:         if ( dynamic_link( "libiomp5.so", iompLinkTable, 1, &libhandle, DYNAMIC_LINK_GLOBAL ) ) {
168:             // We have found the symbol provided by libiomp5 for restoring original thread affinity.
169:             affinity_helper affhelp;
170:             affhelp.protect_affinity_mask( /*restore_process_mask=*/false );
171:             if ( libiomp_try_restoring_original_mask()==0 ) {
172:                 // Now we have the right mask to capture, restored by libiomp.
173:                 const int curMaskSize = BasicMaskSize * numMasks;
174:                 std::memset( processMask, 0, curMaskSize );
175:                 get_thread_affinity_mask( curMaskSize, processMask );
176:             } else
177:                 affhelp.dismiss();  // thread mask has not changed
178:             dynamic_unlink( libhandle );
179:             // Destructor of affinity_helper restores the thread mask (unless dismissed).
180:         }
181: #endif
182:         for ( int m = 0; availableProcs < maxProcs && m < numMasks; ++m ) {
183:             for ( std::size_t i = 0; (availableProcs < maxProcs) && (i < BasicMaskSize * CHAR_BIT); ++i ) {
184:                 if ( CPU_ISSET( i, processMask + m ) )
185:                     ++availableProcs;
186:             }
187:         }
188:         process_mask = processMask;
189:     }
190:     else {
191:         // Failed to get the process affinity mask; assume the whole machine can be used.
192:         availableProcs = (maxProcs == INT_MAX) ? sysconf(_SC_NPROCESSORS_ONLN) : maxProcs;
193:         delete[] processMask;
194:     }
195:     int num_procs = availableProcs > 0 ? availableProcs : 1; // Fail safety strap
196: #if __linux__
197:     int cgroup_num_cpus = INT_MAX;
198:     if (cgroup_info<>::is_cpu_constrained(cgroup_num_cpus)) {
199:         // If cgroup is used, limit the number of processors to the constrained value.
200:         num_procs = std::min(num_procs, cgroup_num_cpus);
201:     }
202: #endif // __linux__
203:     theNumProcs = num_procs;
204:     __TBB_ASSERT( theNumProcs <= sysconf(_SC_NPROCESSORS_ONLN), nullptr);
205: }
