221:     while ((num_args = fscanf(fp, "%u-%u", &lower, &upper)) != EOF) {
222:         switch(num_args) {
223:             case 2: num_cpus += upper - lower + 1; break;
224:             case 1: num_cpus += 1; break;
225:         }
226:         fscanf(fp, ",");
227:     }
228:     fclose(fp);
229:     return (num_cpus > 0) ? num_cpus : 1;
230: }
